const filas = $('Conversaciones del bot').all().map(i => i.json);
const conFecha = filas.filter(f => f.selected_date && f.plate);
const res = $input.all().map(i => i.json);
const out = conFecha.map((f, i) => {
  const r = res[i] || {};
  const items = (r.result && r.result.items) || [];
  const fecha = String(f.selected_date).slice(0, 10);
  const match = items.find(it => String(it.vehicle && it.vehicle.plate || '').toUpperCase() === String(f.plate).toUpperCase() && String(it.date).slice(0, 10) === fecha);
  return { json: { mes: String(f.created_at).slice(0, 7), id_conversation: f.id_conversation, plate: f.plate, model: f.model, sucursal: f.sucursal, created_at: f.created_at, selected_date: fecha, selected_hour: f.selected_hour, service_id: f.service_id, enFord: !!match, estadoFord: match ? match.status : null, origenFord: match ? match.source : null, horaFord: match ? match.date : null, errorFord: r.error && r.error.message ? String(r.error.message).slice(0, 120) : null } };
});
const totales = {};
for (const f of filas) { const m = String(f.created_at).slice(0, 7); totales[m] = totales[m] || { conversaciones: 0, conPatente: 0, eligieronFecha: 0, turnosEnFord: 0 }; totales[m].conversaciones++; if (f.plate) totales[m].conPatente++; if (f.selected_date && f.plate) totales[m].eligieronFecha++; }
for (const o of out) if (o.json.enFord) totales[o.json.mes].turnosEnFord++;
return [{ json: { totales, detalle: out.map(o => o.json) } }];
